1|import "server-only";
2|import { randomUUID } from "node:crypto";
3|import {
4|  MSG_FAILED,
5|  MSG_QUOTA,
6|  MSG_BUDGET,
7|  LOCK_TTL_SEC,
8|  buildCaption,
9|  buildPrompt,
10|  budgetExceeded,
11|  imageCostMicro,
12|  imageKey,
13|  indexKeyFor,
14|  lockKeyFor,
15|  spendKey,
16|} from "@/core/images";
17|import type { ImageGenerator, ImageRequest, ImageResponse, ImageStore, KV } from "@/core/images";
18|import type { ImageEnv } from "./env";
19|import { verifyHuman } from "./human";
20|import { checkQuota, hashIp, quotaKeysFor, refundQuota } from "./quota";
21|
22|export interface ImageContent {
23|  passageText: string;
24|  sceneTitle: string;
25|  sceneClip: string;
26|}
27|
28|export interface OrchestrateDeps {
29|  kv: KV;
30|  store: ImageStore;
31|  generate: ImageGenerator;
32|  env: ImageEnv;
33|  content: ImageContent;
34|  ip: string;
35|  anonId: string;
36|  day: string;
37|  token?: string;
38|}
39|
40|// One pass, no skipped steps: hit -> lock -> human -> quota -> budget ->
41|// generate -> store -> index -> release. Every failure after the reserve
42|// refunds quota and budget and releases the lock.
43|export async function orchestrate(
44|  req: ImageRequest,
45|  deps: OrchestrateDeps,
46|): Promise<ImageResponse> {
47|  const key = imageKey(req);
48|  const indexKey = indexKeyFor(key);
49|  const lockKey = lockKeyFor(key);
50|
51|  const indexed = await deps.kv.get(indexKey);
52|  if (indexed) {
53|    return { status: "ready", url: indexed, cached: true, caption: captionFor(req, deps.content) };
54|  }
55|  const existing = await deps.store.findUrl(key);
56|  if (existing) {
57|    await deps.kv.set(indexKey, existing);
58|    return { status: "ready", url: existing, cached: true, caption: captionFor(req, deps.content) };
59|  }
60|
61|  const token = deps.token ?? randomUUID();
62|  if (!(await deps.kv.setNxEx(lockKey, token, LOCK_TTL_SEC))) return { status: "pending" };
63|  const release = () => deps.kv.releaseIfToken(lockKey, token);
64|
65|  if (!verifyHuman()) {
66|    await release();
67|    return { status: "error", code: "unavailable", message: MSG_FAILED };
68|  }
69|
70|  const keys = quotaKeysFor({ day: deps.day, ip: deps.ip, salt: deps.env.ipSalt, anonId: deps.anonId });
71|  if (!(await checkQuota(deps.kv, keys)).ok) {
72|    await release();
73|    return { status: "error", code: "quota", message: MSG_QUOTA };
74|  }
75|
76|  const total = await deps.kv.incrBy(spendKey(), imageCostMicro());
77|  if (budgetExceeded(total, deps.env.spendCapMicro)) {
78|    await deps.kv.decrBy(spendKey(), imageCostMicro());
79|    await refundQuota(deps.kv, keys);
80|    await release();
81|    return { status: "error", code: "budget", message: MSG_BUDGET };
82|  }
83|  const refundSpend = () => deps.kv.decrBy(spendKey(), imageCostMicro());
84|
85|  let bytes: Uint8Array;
86|  try {
87|    bytes = await deps.generate.generate(
88|      buildPrompt({
89|        kind: req.kind,
90|        passageText: deps.content.passageText,
91|        sceneTitle: deps.content.sceneTitle,
92|        sceneClip: deps.content.sceneClip,
93|      }),
94|    );
95|  } catch {
96|    await refundSpend();
97|    await refundQuota(deps.kv, keys);
98|    await release();
99|    console.error("image generate failed");
100|    return { status: "error", code: "unavailable", message: MSG_FAILED };
101|  }
102|
103|  try {
104|    const url = await deps.store.save(key, bytes);
105|    await deps.kv.set(indexKey, url);
106|    await release();
107|    return { status: "ready", url, cached: false, caption: captionFor(req, deps.content) };
108|  } catch {
109|    // A lost save race leaves the winner's file behind; backfill from it.
110|    const raced = await deps.store.findUrl(key);
111|    if (raced) {
112|      await deps.kv.set(indexKey, raced);
113|      await release();
114|      return { status: "ready", url: raced, cached: true, caption: captionFor(req, deps.content) };
115|    }
116|    await refundSpend();
117|    await refundQuota(deps.kv, keys);
118|    await release();
119|    console.error("image store failed");
120|    return { status: "error", code: "unavailable", message: MSG_FAILED };
121|  }
122|}
123|
124|function captionFor(req: ImageRequest, content: ImageContent): string {
125|  return buildCaption({
126|    kind: req.kind,
127|    sceneTitle: content.sceneTitle,
128|    passageText: content.passageText,
129|  });
130|}

