1|import "server-only";
2|import { loadOzBook } from "@/server/books";
3|import { MSG_BAD_REQUEST, MSG_UNAVAILABLE, parseImageRequest, validateAgainstBook } from "@/core/images";
4|import type { ImageRequest, ImageResponse } from "@/core/images";
5|import { readImageEnv } from "./env";
6|import { createRestKV } from "./kv";
7|import { createBlobStore } from "./blob";
8|import { createMetaClient } from "./meta";
9|import { orchestrate } from "./orchestrate";
10|import type { ImageContent } from "./orchestrate";
11|import { issueAnonId, parseAnonCookie, serializeAnonCookie, verifyAnonCookie } from "./cookies";
12|import { clientIp, utcDay } from "./quota";
13|
14|function toResponse(res: ImageResponse): { json: ImageResponse; status: number } {
15|  if (res.status === "ready" || res.status === "pending") return { json: res, status: 200 };
16|  const status = res.code === "bad_request" ? 400 : res.code === "quota" ? 429 : 503;
17|  return { json: res, status };
18|}
19|
20|export async function handleImagesPost(req: Request): Promise<Response> {
21|  let parsed: ImageRequest;
22|  try {
23|    parsed = parseImageRequest(await req.json());
24|  } catch {
25|    return Response.json(
26|      { status: "error", code: "bad_request", message: MSG_BAD_REQUEST } satisfies ImageResponse,
27|      { status: 400 },
28|    );
29|  }
30|
31|  let env;
32|  try {
33|    env = readImageEnv();
34|  } catch {
35|    return Response.json(
36|      { status: "error", code: "unavailable", message: MSG_UNAVAILABLE } satisfies ImageResponse,
37|      { status: 503 },
38|    );
39|  }
40|
41|  const { book, scenes } = loadOzBook();
42|  try {
43|    validateAgainstBook(
44|      parsed,
45|      {
46|        id: book.id,
47|        textVersion: book.textVersion,
48|        paragraphNs: new Set(book.paragraphs.map((p) => p.n)),
49|        sceneIds: new Set(scenes.map((s) => s.id)),
50|      },
51|    );
52|  } catch {
53|    return Response.json(
54|      { status: "error", code: "bad_request", message: MSG_BAD_REQUEST } satisfies ImageResponse,
55|      { status: 400 },
56|    );
57|  }
58|
59|  const byN = new Map(book.paragraphs.map((p) => [p.n, p.text]));
60|  const sceneOf = scenes.find((s) =>
61|    parsed.kind === "passage" ? parsed.n >= s.start_n && parsed.n <= s.end_n : s.id === parsed.sceneId,
62|  );
63|  const sceneParas = sceneOf
64|    ? book.paragraphs.filter((p) => p.n >= sceneOf.start_n && p.n <= sceneOf.end_n)
65|    : [];
66|  const content: ImageContent = {
67|    passageText: parsed.kind === "passage" ? (byN.get(parsed.n) ?? "") : "",
68|    sceneTitle: sceneOf?.title ?? "",
69|    sceneClip: sceneParas.map((p) => p.text).join(" "),
70|  };
71|
72|  const cookieValue = parseAnonCookie(req.headers.get("cookie"));
73|  let anonId = cookieValue ? verifyAnonCookie(cookieValue, env.sessionSecret) : null;
74|  let setCookie: string | null = null;
75|  if (!anonId) {
76|    const issued = issueAnonId(env.sessionSecret);
77|    anonId = issued.id;
78|    setCookie = serializeAnonCookie(issued.value);
79|  }
80|
81|  const res = await orchestrate(parsed, {
82|    kv: createRestKV(env.upstashUrl, env.upstashToken),
83|    store: createBlobStore(),
84|    generate: createMetaClient(env.metaKey),
85|    env,
86|    content,
87|    ip: clientIp(req.headers.get("x-forwarded-for")),
88|    anonId,
89|    day: utcDay(),
90|  });
91|
92|  const { json, status } = toResponse(res);
93|  const headers = setCookie ? { "Set-Cookie": setCookie } : undefined;
94|  return Response.json(json, { status, headers });
95|}

