1|import "server-only";
2|import { list, put } from "@vercel/blob";
3|import type { ImageStore } from "@/core/images";
4|
5|// Blob wrappers. Paths are deterministic and public; routes return URLs,
6|// never bytes. @vercel/blob reads BLOB_READ_WRITE_TOKEN from env.
7|export function createBlobStore(): ImageStore {
8|  return {
9|    // list stands in for head: a deterministic path has no known URL
10|    // until the store prefix is resolved, so match the exact pathname.
11|    async findUrl(path: string): Promise<string | null> {
12|      const page = await list({ prefix: path, limit: 10 });
13|      return page.blobs.find((b) => b.pathname === path)?.url ?? null;
14|    },
15|    async save(path: string, bytes: Uint8Array): Promise<string> {
16|      const blob = await put(path, Buffer.from(bytes), {
17|        access: "public",
18|        addRandomSuffix: false,
19|        allowOverwrite: false,
20|        contentType: "image/webp",
21|        cacheControlMaxAge: 31536000,
22|      });
23|      return blob.url;
24|    },
25|  };
26|}

