1|import { describe, expect, it } from "vitest";
2|import { createMemoryKV, spendKey } from "@/core/images";
3|import type { ImageGenerator, ImageRequest, ImageStore } from "@/core/images";
4|import type { ImageEnv } from "./env";
5|import { orchestrate } from "./orchestrate";
6|import type { OrchestrateDeps } from "./orchestrate";
7|
8|const env: ImageEnv = {
9|  upstashUrl: "https://x",
10|  upstashToken: "t",
11|  metaKey: "m",
12|  sessionSecret: "s",
13|  ipSalt: "salt",
14|  spendCapMicro: 10_000_000,
15|};
16|
17|const content = {
18|  passageText: "Dorothy lived in the midst of the great Kansas prairies.",
19|  sceneTitle: "Gray Life on the Prairie",
20|  sceneClip: "Gray prairie and a small house.",
21|};
22|
23|const passage: ImageRequest = { kind: "passage", bookId: "oz", textVersion: "t", n: 3 };
24|
25|function deps(over: Partial<OrchestrateDeps> = {}): OrchestrateDeps {
26|  const files = new Map<string, Uint8Array>();
27|  const store: ImageStore = {
28|    findUrl: async (path) =>
29|      files.has(path) ? `https://blob.example/${path}` : null,
30|    save: async (path, bytes) => {
31|      if (files.has(path)) throw new Error("overwrite");
32|      files.set(path, bytes);
33|      return `https://blob.example/${path}`;
34|    },
35|  };
36|  const generate: ImageGenerator = {
37|    generate: async () => new Uint8Array([1, 2, 3]),
38|  };
39|  return {
40|    kv: createMemoryKV(),
41|    store,
42|    generate,
43|    env,
44|    content,
45|    ip: "1.2.3.4",
46|    anonId: "anon-1",
47|    day: "2026-10-27",
48|    ...over,
49|  };
50|}
51|
52|describe("orchestrate", () => {
53|  it("returns a cached hit without touching Meta, quota, or budget", async () => {
54|    const d = deps();
55|    let calls = 0;
56|    d.generate = { generate: async () => (calls++, new Uint8Array([9])) };
57|    const first = await orchestrate(passage, d);
58|    expect(first.status).toBe("ready");
59|    expect(calls).toBe(1);
60|
61|    const d2 = deps({ kv: d.kv, store: d.store, generate: d.generate });
62|    const second = await orchestrate(passage, d2);
63|    expect(second).toMatchObject({ status: "ready", cached: true });
64|    expect(calls).toBe(1);
65|    expect(await d.kv.get(spendKey())).toBe("10000");
66|  });
67|
68|  it("backfills the index from Blob when Redis missed", async () => {
69|    const d = deps();
70|    await d.store.save("images/oz/t/v1/p3.webp", new Uint8Array([1]));
71|    let calls = 0;
72|    d.generate = { generate: async () => (calls++, new Uint8Array([9])) };
73|    const res = await orchestrate(passage, d);
74|    expect(res).toMatchObject({ status: "ready", cached: true });
75|    expect(calls).toBe(0);
76|  });
77|
78|  it("gives pending to a second requester holding no lock", async () => {
79|    const d = deps();
