1|// Pure image logic: validation, cache keys, prompts, quota and budget
2|// helpers. No env reads, no network, no secrets. Server modules inject
3|// the KV, store, and generator clients defined here.
4|import { IMAGE_COST_MICRO, PROMPT_VERSION } from "./types";
5|import type { ImageKind, ImageRequest } from "./types";
6|
7|export type { ImageErrorCode, ImageKind, ImageRequest, ImageResponse } from "./types";
8|
9|export const DAILY_IMAGE_LIMIT = 5;
10|export const QUOTA_TTL_SEC = 48 * 3600;
11|export const LOCK_TTL_SEC = 150;
12|export const MAX_PASSAGE_CHARS = 600;
13|export const MAX_SCENE_CLIP_CHARS = 1200;
14|
15|export const MSG_BAD_REQUEST = "La solicitud no es válida. Vuelve a intentarlo.";
16|export const MSG_QUOTA = "Alcanzaste tu límite de 5 imágenes por día. Vuelve mañana.";
17|export const MSG_BUDGET = "Se alcanzó el límite de generación. Vuelve a intentarlo más tarde.";
18|export const MSG_UNAVAILABLE = "Las imágenes no están disponibles por ahora.";
19|export const MSG_FAILED = "No se pudo generar la imagen. Vuelve a intentarlo.";
20|export const MSG_RETRY = "La imagen tarda más de lo esperado. Vuelve a intentarlo.";
21|
22|export class ImageValidationError extends Error {
23|  constructor() {
24|    super("invalid image request");
25|    this.name = "ImageValidationError";
26|  }
27|}
28|
29|// Minimal store surface the route needs; Upstash REST and Blob clients
30|// implement these in server/, tests use the memory fake below.
31|export interface KV {
32|  get(key: string): Promise<string | null>;
33|  setNxEx(key: string, value: string, exSec: number): Promise<boolean>;
34|  set(key: string, value: string): Promise<void>;
35|  incr(key: string): Promise<number>;
36|  incrBy(key: string, by: number): Promise<number>;
37|  decr(key: string): Promise<number>;
38|  decrBy(key: string, by: number): Promise<number>;
39|  expire(key: string, sec: number): Promise<void>;
40|  releaseIfToken(key: string, token: string): Promise<boolean>;
41|}
42|
43|export interface ImageStore {
44|  findUrl(path: string): Promise<string | null>;
45|  save(path: string, bytes: Uint8Array): Promise<string>;
46|}
47|
48|export interface ImageGenerator {
49|  generate(prompt: string): Promise<Uint8Array>;
50|}
51|
52|function isRecord(json: unknown): json is Record<string, unknown> {
53|  return typeof json === "object" && json !== null && !Array.isArray(json);
54|}
55|
56|// Strict parse at the trust boundary: exact fields only, so a client
57|// bug cannot silently spend budget on a misread request.
58|export function parseImageRequest(json: unknown): ImageRequest {
59|  if (!isRecord(json)) throw new ImageValidationError();
60|  const { kind } = json;
61|  if (kind === "passage") {
62|    const keys = Object.keys(json).sort().join(",");
63|    if (keys !== "bookId,kind,n,textVersion") throw new ImageValidationError();
64|    if (typeof json.bookId !== "string" || json.bookId.length === 0) throw new ImageValidationError();
65|    if (typeof json.textVersion !== "string" || json.textVersion.length === 0) {
66|      throw new ImageValidationError();
67|    }
68|    if (typeof json.n !== "number" || !Number.isInteger(json.n)) throw new ImageValidationError();
69|    return { kind: "passage", bookId: json.bookId, textVersion: json.textVersion, n: json.n };
70|  }
71|  if (kind === "scene") {
72|    const keys = Object.keys(json).sort().join(",");
73|    if (keys !== "bookId,kind,sceneId,textVersion") throw new ImageValidationError();
74|    if (typeof json.bookId !== "string" || json.bookId.length === 0) throw new ImageValidationError();
75|    if (typeof json.textVersion !== "string" || json.textVersion.length === 0) {
76|      throw new ImageValidationError();
77|    }
78|    if (typeof json.sceneId !== "string" || json.sceneId.length === 0) throw new ImageValidationError();
79|    return { kind: "scene", bookId: json.bookId, textVersion: json.textVersion, sceneId: json.sceneId };
80|  }
81|  throw new ImageValidationError();
82|}
83|
84|export interface BookRef {
85|  id: string;
86|  textVersion: string;
87|  paragraphNs: Set<number>;
88|  sceneIds: Set<string>;
89|}
90|
91|// Checks the parsed request against the frozen book text.
92|export function validateAgainstBook(req: ImageRequest, book: BookRef): void {
93|  if (req.bookId !== book.id) throw new ImageValidationError();
94|  if (req.textVersion !== book.textVersion) throw new ImageValidationError();
95|  if (req.kind === "passage") {
96|    if (!book.paragraphNs.has(req.n)) throw new ImageValidationError();
97|    return;
98|  }
99|  if (!book.sceneIds.has(req.sceneId)) throw new ImageValidationError();
100|}
101|
102|// One paragraph maps to one image; one scene maps to one image.
103|export function imageKey(req: ImageRequest): string {
104|  const base = `images/${req.bookId}/${req.textVersion}/${PROMPT_VERSION}`;
105|  return req.kind === "passage" ? `${base}/p${req.n}.webp` : `${base}/scene-${req.sceneId}.webp`;
106|}
107|
108|export function indexKeyFor(key: string): string {
109|  return `img:index:${key}`;
110|}
111|
112|export function lockKeyFor(key: string): string {
113|  return `img:lock:${key}`;
114|}
115|
116|export function quotaKeys(args: { day: string; ipHash: string; anonId: string }): {
117|  ip: string;
118|  anon: string;
