10|    async generate(prompt: string): Promise<Uint8Array> {
11|      const res = await fetch(ENDPOINT, {
12|        method: "POST",
13|        headers: { Authorization: `Bearer ${apiKey}`, "Content-Type": "application/json" },
14|        body: JSON.stringify({
15|          model: "muse-image-1.0",
16|          prompt,
17|          n: 1,
18|          size: "1024x1024",
19|          output_format: "webp",
20|          response_format: "b64_json",
21|        }),
22|        signal: AbortSignal.timeout(100_000),
23|      });
24|      if (!res.ok) throw new Error(`meta status ${res.status}`);
25|      const json = (await res.json()) as { data?: Array<{ b64_json?: string }> };
26|      const b64 = json.data?.[0]?.b64_json;
27|      if (!b64) throw new Error("meta empty image");
28|      return new Uint8Array(Buffer.from(b64, "base64"));
29|    },
