1|import "server-only";
2|import { createHmac, randomBytes, timingSafeEqual } from "node:crypto";
3|
4|export const ANON_COOKIE = "img_anon";
5|
6|function sign(id: string, secret: string): string {
7|  return createHmac("sha256", secret).update(id).digest("hex");
8|}
9|
10|export function issueAnonId(secret: string): { id: string; value: string } {
11|  const id = randomBytes(16).toString("hex");
12|  return { id, value: `${id}.${sign(id, secret)}` };
13|}
14|
15|// Returns the id when the signature matches, else null. Compare runs in
16|// constant time so a forged cookie reveals nothing about the secret.
17|export function verifyAnonCookie(value: string | null | undefined, secret: string): string | null {
18|  if (!value) return null;
19|  const dot = value.indexOf(".");
20|  if (dot < 1) return null;
21|  const id = value.slice(0, dot);
22|  const sig = value.slice(dot + 1);
23|  const expected = sign(id, secret);
24|  if (sig.length !== expected.length) return null;
25|  const ok = timingSafeEqual(Buffer.from(sig), Buffer.from(expected));
26|  return ok ? id : null;
27|}
28|
29|export function parseAnonCookie(header: string | null | undefined): string | null {
30|  if (!header) return null;
31|  for (const part of header.split(";")) {
32|    const eq = part.indexOf("=");
33|    if (eq < 0) continue;
34|    if (part.slice(0, eq).trim() === ANON_COOKIE) return part.slice(eq + 1).trim();
35|  }
36|  return null;
37|}
38|
39|export function serializeAnonCookie(value: string): string {
40|  return `${ANON_COOKIE}=${value}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=31536000`;
41|}

